<?= $this->extend('layouts/admin') ?>
<?= $this->section('content') ?>
<section class="list-head"><div><p>Content manager</p><h1><?= esc($meta['label']) ?></h1></div><?php if ($entity !== 'inquiries'): ?><a class="primary" href="<?= site_url('admin/' . $entity . '/new') ?>">Add <?= rtrim(strtolower($meta['label']), 's') ?></a><?php endif ?></section>
<form class="content-filter" method="get"><input name="q" value="<?= esc($search) ?>" placeholder="Search <?= strtolower($meta['label']) ?>"><select name="status"><option value="">All statuses</option><?php foreach ($entity === 'inquiries' ? ['new', 'in_progress', 'resolved'] : (($entity === 'pages' || $entity === 'posts') ? ['draft', 'in_review', 'scheduled', 'published'] : ['draft', 'published']) as $option): ?><option value="<?= $option ?>" <?= $status === $option ? 'selected' : '' ?>><?= ucwords(str_replace('_', ' ', $option)) ?></option><?php endforeach ?></select><button>Filter</button><?php if ($search || $status): ?><a href="<?= site_url('admin/' . $entity) ?>">Clear</a><?php endif ?></form>
<div class="table-wrap"><table><thead><tr><th>Title / name</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><strong><?= esc($row['title'] ?? $row['name'] ?? $row['source_path'] ?? '') ?></strong><small><?= esc($row['slug'] ?? $row['email'] ?? $row['target_url'] ?? '') ?></small></td><td><span class="badge <?= esc($row['status'] ?? '') ?>"><?= esc($row['status'] ?? ($row['http_code'] ?? '')) ?></span></td><td><?= esc($row['updated_at'] ?? '') ?></td><td class="actions"><a href="<?= site_url('admin/' . $entity . '/' . $row['id'] . '/edit') ?>">Edit</a><?php if ($adminRole === 'admin'): ?><form method="post" action="<?= site_url('admin/' . $entity . '/' . $row['id'] . '/delete') ?>" onsubmit="return confirm('Delete this item?')"><?= csrf_field() ?><button>Delete</button></form><?php endif ?></td></tr><?php endforeach ?><?php if (! $rows): ?><tr><td colspan="4">Nothing here yet.</td></tr><?php endif ?></tbody></table></div>
<?= $this->endSection() ?>
